const listImportLedgerConflicts = `-- name: ListImportLedgerConflicts :many
SELECT id, entity_kind, source_id, vidra_id, status, note, created_at, updated_at, source_value, applied_value FROM peertube_import_ledger
WHERE status IN ('skipped', 'failed', 'unsupported') OR note <> ''
ORDER BY entity_kind, source_id
LIMIT $1
`

// The rows the conflict policy touched (renamed/merged/skipped/failed) — the
// dry-run "conflicts" report and the operator's post-import audit.
func (q *Queries) ListImportLedgerConflicts(ctx context.Context, limit int32) ([]PeertubeImportLedger, error) {
	rows, err := q.db.Query(ctx, listImportLedgerConflicts, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PeertubeImportLedger
	for rows.Next() {
		var i PeertubeImportLedger
		if err := rows.Scan(
			&i.ID,
			&i.EntityKind,
			&i.SourceID,
			&i.VidraID,
			&i.Status,
			&i.Note,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SourceValue,
			&i.AppliedValue,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

