const upsertImportLedgerEntry = `-- name: UpsertImportLedgerEntry :one
INSERT INTO peertube_import_ledger (entity_kind, source_id, vidra_id, status, note)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (entity_kind, source_id)
DO UPDATE SET vidra_id = EXCLUDED.vidra_id,
              status   = EXCLUDED.status,
              note     = EXCLUDED.note,
              updated_at = now()
RETURNING id, entity_kind, source_id, vidra_id, status, note, created_at, updated_at, source_value, applied_value
`

type UpsertImportLedgerEntryParams struct {
	EntityKind string      `json:"entity_kind"`
	SourceID   string      `json:"source_id"`
	VidraID    pgtype.UUID `json:"vidra_id"`
	Status     string      `json:"status"`
	Note       string      `json:"note"`
}

// Record (or update) the outcome of importing one source entity. Called in the
// SAME transaction as the entity insert so the map and the row commit atomically
// (a crash between them cannot leave a dangling half-import). ON CONFLICT keeps
// the re-import a no-op-that-updates rather than a duplicate.
func (q *Queries) UpsertImportLedgerEntry(ctx context.Context, arg UpsertImportLedgerEntryParams) (PeertubeImportLedger, error) {
	row := q.db.QueryRow(ctx, upsertImportLedgerEntry,
		arg.EntityKind,
		arg.SourceID,
		arg.VidraID,
		arg.Status,
		arg.Note,
	)
	var i PeertubeImportLedger
	err := row.Scan(
		&i.ID,
		&i.EntityKind,
		&i.SourceID,
		&i.VidraID,
		&i.Status,
		&i.Note,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SourceValue,
		&i.AppliedValue,
	)
	return i, err
}
